function loadProfile(){
  try{
    const loaded=saveSlots.load(),p=loaded?.payload;if(!p)return;totalPlaySeconds=Math.max(0,Number(loaded.playSeconds)||0);saveRecovered=Boolean(loaded.recovered);
    Object.assign(STATE,p.state||{});STATE.level=levelFromXp(STATE.xp);
    (p.inventory||[]).forEach(([k,v])=>inventory.set(+k,v));
    (p.cosmetics||[]).forEach(x=>cosmeticOwned.add(x));
    Object.assign(equipped,p.equipped||{});
    (p.claimedContracts||[]).forEach(x=>claimedContracts.add(x));
    (p.claimedCollections||[]).forEach(x=>claimedCollections.add(x));
    (p.visited||[]).forEach(x=>visitedRegions.add(x));
    (p.affinity||[]).forEach(([k,v])=>affinity.set(k,v));
    Object.assign(metrics,p.metrics||{});career.restore(p.career,careerMetrics());cityLife.restore(p.life);harborNetwork.restore(p.harbor,{day:cityLife.profile.day,hour:cityLife.profile.worldHour});cityPopulation.restore(p.population);citizenRelations.restore(p.citizenRelations);weatherDirector.restore(p.weather);fishing.restore(p.fishing);fishery.restore(p.fishery);worldActivities.restore(p.worldActivities);workshop.restore(p.workshop);storyMissions.restore(p.story);onboarding.restore(p.onboarding);navigation.restore(p.navigation);raceEvents.restore(p.raceEvents);rivalTour.restore(p.rivalTour);cityJobs.restore(p.cityJobs);cityDelivery.restore(p.cityDelivery);activeRaceEvent=raceEvents.selected;activeRaceRoute=raceRoutes.get(activeRaceEvent.id);syncWorkshopEffects();
  }catch(e){console.info('profile reset',e)}
}
