const harborClock=()=>({day:cityLife.profile.day,hour:cityLife.profile.worldHour});
function formatHarborDuration(hours){const total=Math.max(0,Math.ceil(hours*60)),h=Math.floor(total/60),m=total%60;return h?`${h}H ${String(m).padStart(2,'0')}M`:`${m}M`}
