  $('#harborTime').textContent=active.status==='ready'?(i18n.lang==='ko'?'보고 가능':'READY TO REPORT'):formatHarborDuration(snapshot.timeRemaining);$('#harborReward').textContent=`+${active.reward.credits.toLocaleString()} CR · +${active.reward.standing} ST`;$('#harborFill').style.width=`${Math.round(snapshot.progress*100)}%`;
