function performCityJob(jobId){
  const result=cityJobs.work(jobId,cityJobContext());
  if(!result.ok){
    if(result.reason==='locked')return toast(`CITY WORK LOCKED · ${result.job.unlockRep.toLocaleString()} REP REQUIRED`);
    if(result.reason==='closed')return toast(`SHIFT CLOSED · OPEN ${formatLifeHour(result.job.open)}–${formatLifeHour(result.job.close)}`);
    if(result.reason==='worked')return toast('오늘 이 직업의 근무를 이미 마쳤습니다');
    if(result.reason==='needs')return toast(`근무 준비가 부족합니다 · ${result.requirements.map(([key,value])=>`${key.toUpperCase()} ${value}`).join(' · ')}`);
    return toast('선택한 근무를 시작할 수 없습니다');
  }
  cityLife.applyRoutine({hours:result.hours,effects:result.effects,activityId:`job:${jobId}`});
  const xp=65+result.record.level*8,rep=8+result.record.level*2;award({credits:result.pay,xp,rep,season:Math.round(xp*.7)});
  recordHarborEvent('life',{facilityId:result.job.facilityId,actionId:`job:${jobId}`,jobId,count:1});recordStoryEvent('life',{facilityId:result.job.facilityId,actionId:`job:${jobId}`,jobId,count:1});onboarding.record('lifeAction');
  recordCitizenEvent('job',{facilityId:result.job.facilityId,jobId,count:1});
  audioDirector.cue(result.promotion?'jobPromotion':'jobComplete',1);gamepadDirector.pulse(result.promotion ? .82 : .55,result.promotion?190:115);
  toast(`${lifeText(result.job.name)} · +${result.pay.toLocaleString()} CR · SKILL LV ${result.record.level}${result.promotion?' · PROMOTION':''}`);
  saveProfile();renderLifePanel(cityLife.currentFacility());updateLifeHud();
}
