  if(cityLife.mode==='foot'){const guide=cityLife.facilityGuide({x:px,z:pz},heading);for(let index=0;index<CITY_FACILITIES.length;index++){const facility=CITY_FACILITIES[index],status=cityLife.facilityStatus(facility.id),x=W/2+facility.exterior.x*s,y=H/2+facility.exterior.z*s,current=guide?.facility.id===facility.id;ctx.beginPath();ctx.fillStyle=status.open?`#${facility.accent.toString(16).padStart(6,'0')}`:'#ff6659';ctx.strokeStyle=current?'#ffffff':'#061015';ctx.lineWidth=current?2.4:1.2;ctx.arc(x,y,current?4.8:3.3,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#061015';ctx.font='900 5px Arial';ctx.textAlign='center';ctx.fillText(String(index+1),x,y+1.8)}}
