  const deliverySnapshot=cityDelivery.snapshot({x:px,z:pz});if(deliverySnapshot.active){const pulse=5+Math.sin(STATE.time*4.6)*1.5,target=deliverySnapshot.target;ctx.strokeStyle='#ffc86a';ctx.lineWidth=2.7;ctx.beginPath();ctx.arc(W/2+target.x*s,H/2+target.z*s,pulse,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#65efa2';ctx.beginPath();ctx.arc(W/2+target.x*s,H/2+target.z*s,2.3,0,Math.PI*2);ctx.fill()}
  const storyWaypoint=resolveStoryWaypoint();if(storyWaypoint&&storyWaypoint.onDuty!==false){const pulse=5+Math.sin(STATE.time*3.2)*1.5;ctx.strokeStyle='#b68cff';ctx.lineWidth=2.7;ctx.beginPath();ctx.arc(W/2+storyWaypoint.x*s,H/2+storyWaypoint.z*s,pulse,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#e4d4ff';ctx.beginPath();ctx.arc(W/2+storyWaypoint.x*s,H/2+storyWaypoint.z*s,2.2,0,Math.PI*2);ctx.fill()}
  const tutorialWaypoint=coastLicenseWaypoint();if(tutorialWaypoint){const pulse=5.5+Math.sin(STATE.time*3.8)*1.7;ctx.strokeStyle='#ffc86a';ctx.lineWidth=2.8;ctx.beginPath();ctx.arc(W/2+tutorialWaypoint.x*s,H/2+tutorialWaypoint.z*s,pulse,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#ffe2a6';ctx.beginPath();ctx.arc(W/2+tutorialWaypoint.x*s,H/2+tutorialWaypoint.z*s,2.4,0,Math.PI*2);ctx.fill()}
  const customWaypoint=navigation.profile.waypoint;if(customWaypoint){const pulse=5+Math.sin(STATE.time*4.1)*1.6;ctx.strokeStyle='#53e6ff';ctx.lineWidth=2.7;ctx.beginPath();ctx.arc(W/2+customWaypoint.x*s,H/2+customWaypoint.z*s,pulse,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#d7faff';ctx.beginPath();ctx.arc(W/2+customWaypoint.x*s,H/2+customWaypoint.z*s,2.3,0,Math.PI*2);ctx.fill()}
